export function resolveModelProvider(
  modelId: string,
  provider?: ModelProvider | string
): ModelProvider {
  if (
    provider === "qwen" ||
    provider === "ollama" ||
    provider === "baai" ||
    provider === "microsoft" ||
    provider === "huggingface"
  ) {
    return provider;
  }
  const lower = modelId.toLowerCase();
  if (lower.includes("qwen")) return "qwen";
  if (lower.includes("baai") || lower.includes("bge")) return "baai";
  if (lower.includes("ms-marco") || lower.includes("microsoft")) return "microsoft";
  if (lower.includes("/")) return "huggingface";
  return "ollama";
}

export const ModelBrandIcon: React.FC<
  IconProps & { modelId: string; provider?: ModelProvider | string }
> = ({ modelId, provider, size = 16, className = "" }) => {
  const resolved = resolveModelProvider(modelId, provider);
  switch (resolved) {
    case "qwen":
      return <QwenLogo size={size} className={className} />;
    case "baai":
      return <BAAILogo size={size} className={className} />;
    case "microsoft":
      return <MicrosoftLogo size={size} className={className} />;
    case "huggingface":
      return <HuggingFaceLogo size={size} className={className} />;
    default:
      return <OllamaLogo size={size} className={className} />;
  }
};

export const AcceleratorIcon: React.FC<
  IconProps & { accelerator?: string | null }
> = ({ accelerator, size = 16, className = "" }) => {
  const lower = (accelerator || "").toLowerCase();
  if (lower.includes("nvidia") || lower.includes("cuda") || lower.includes("rtx") || lower.includes("gtx") || lower.includes("geforce")) {
    return <NvidiaLogo size={size} className={className} />;
  }
  if (lower.includes("apple") || lower.includes("metal") || lower.includes("mps")) {
    return <AppleLogo size={size} className={className} />;
  }
  if (lower.includes("amd") || lower.includes("radeon") || lower.includes("rocm") || lower.includes("ryzen")) {
    return <AmdLogo size={size} className={className} />;
  }
  if (lower.includes("intel") || lower.includes("core") || lower.includes("xeon")) {
    return <IntelLogo size={size} className={className} />;
  }
  return <OllamaLogo size={size} className={className} />;
};
